// Copies the compiled ElysianPyre ABI and bytecode into the website, and the runtime code hash
// into the Worker, so the admin page deploys exactly the audited code and the Worker accepts only it.
// Run after `npx hardhat compile`: npm run export-abi
import { readFileSync, writeFileSync } from 'node:fs';
import { keccak256 } from 'viem';

const a = JSON.parse(readFileSync('artifacts/contracts/ElysianPyre.sol/ElysianPyre.json', 'utf8'));
writeFileSync('web/assets/app/abi.js',
  '// Generated by scripts/export-abi.mjs from the compiled contract. Do not edit by hand.\n' +
  `export const pyreAbi = ${JSON.stringify(a.abi)};\n` +
  `export const pyreBytecode = ${JSON.stringify(a.bytecode)};\n`);
const hash = keccak256(a.deployedBytecode);
writeFileSync('worker/code-hash.js',
  '// Generated by scripts/export-abi.mjs: keccak256 of the ElysianPyre runtime bytecode.\n' +
  `export const PYRE_CODE_HASH = ${JSON.stringify(hash)};\n`);
console.log('abi + bytecode -> web/assets/app/abi.js; code hash', hash, '-> worker/code-hash.js');
